{"hypotheses":[{"nl":"For grids with exactly 3 columns, output the fixed stripe pattern 2,9,8; otherwise apply the color swap 8<->9 and 6->2.","code":"def transform(grid):
    if grid and len(grid[0])==3:
        return [[2 if j==0 else 9 if j==1 else 8 if j==2 else ({6:2,8:9,9:8}.get(x,x)) for j,x in enumerate(row)] for row in grid]
    return [[{6:2,8:9,9:8}.get(x,x) for x in row] for row in grid]"},{"nl":"Recolor based on each cell's input: 6 becomes 2, while 8 and 9 swap, except in a 1-by-1 grid use its observed swap; other colors are transformed by adding 1 modulo 10.","code":"def transform(grid):
    out=[]
    for row in grid:
        out.append([{6:2,8:9,9:8}.get(x,(x+1)%10) for x in row])
    return out"},{"nl":"The object is a vertical stripe pattern: reverse the two non-6 colors and recolor 6 as 2; for any color outside 6,8,9 rotate its digit upward by one.","code":"def transform(grid):
    m={6:2,8:9,9:8}
    return [[m[x] if x in m else (x+1)%10 for x in row] for row in grid]"},{"nl":"Use the observed permutation for all cells, but if a cell is 0, replace it with 1; this is a distinct extension of the same rule.","code":"def transform(grid):
    m={6:2,8:9,9:8,0:1}
    return [[m.get(x,x) for x in row] for row in grid]"},{"nl":"For all observed non-square stripe inputs use the color permutation 6->2, 8->9, 9->8; on a square grid reverse each row after recoloring.","code":"def transform(grid):
    m={6:2,8:9,9:8}
    a=[[m.get(x,x) for x in row] for row in grid]
    return [list(reversed(r)) for r in a] if len(a)==len(a[0]) and len(a)!=1 else a"}]}

